    /** 当前本轮运行分钟：最新读数累计工时 - 最近保养锚点工时（无保养从 0 计）。 */
    private long currentRunMinutes(String equipmentId, Equipment equipment,
                                   Optional<MaintenanceRecord> last) {
        long latestCumulative = repository.findLatestReading(equipmentId)
